$GLOBALS['csv_diag']=[];
function out(array $x,int $code=200): never {http_response_code($code);echo json_encode($x,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_INVALID_UTF8_SUBSTITUTE);exit;}
function norm(string $s): string{return preg_replace('/[^a-zа-я0-9]+/u','',mb_strtolower(trim($s)))??'';}
function utf8(string $s): string{if(str_starts_with($s,"\xEF\xBB\xBF"))return substr($s,3);if(str_starts_with($s,"\xFF\xFE"))return mb_convert_encoding(substr($s,2),'UTF-8','UTF-16LE');if(str_starts_with($s,"\xFE\xFF"))return mb_convert_encoding(substr($s,2),'UTF-8','UTF-16BE');if(mb_check_encoding($s,'UTF-8'))return $s;return mb_convert_encoding($s,'UTF-8','Windows-1251');}
function knownHeaderCount(array $row): int{$known=['id','guid','uuid','код','код товара','идентификатор','sku','артикул','barcode','штрихкод','name','title','наименование','название','товар','price','цена','category','категория','группа','parent_id'];$set=array_map('norm',$known);$n=0;foreach($row as $v)if(in_array(norm((string)$v),$set,true))$n++;return $n;}
function csvAll(string $path): array{$raw=file_get_contents($path);if($raw===false)throw new RuntimeException('read_failed');$raw=str_replace("\0",'',utf8($raw));if(trim($raw)==='')throw new RuntimeException('csv_empty:'.basename($path));$physical=preg_split('/\r\n|\n|\r/',$raw)?:[];$first='';foreach($physical as $ln){if(trim($ln)!==''){$first=$ln;break;}}$c=[';'=>substr_count($first,';'),','=>substr_count($first,','),"\t"=>substr_count($first,"\t")];arsort($c);$d=(string)array_key_first($c);$all=[];foreach($physical as $ln){if(trim($ln)==='')continue;$r=str_getcsv($ln,$d,'"','\\');if(count(array_filter($r,fn($v)=>trim((string)$v)!=='')))$all[]=$r;}if(!$all)return[[],[],$d,false];$firstRow=array_shift($all);$hasHeader=knownHeaderCount($firstRow)>=1;if($hasHeader){$h=$firstRow;$rows=$all;}else{$rows=array_merge([$firstRow],$all);$width=0;foreach(array_slice($rows,0,100) as $r)$width=max($width,count($r));$h=[];for($i=0;$i<$width;$i++)$h[]='col_'.$i;}return[$h,$rows,$d,$hasHeader];}
function col(array $h,array $aliases): ?int{foreach($h as $i=>$v){$n=norm((string)$v);foreach($aliases as $a)if($n===norm($a))return $i;}return null;}
function val(array $r,?int $i): string{return $i===null?'':trim((string)($r[$i]??''));}
function money(string $x): int{$x=preg_replace('/[^0-9,.-]/u','',$x)??'';$x=str_replace(',','.',$x);return is_numeric($x)?(int)round((float)$x):0;}
function authImport(array $config): void{$given=(string)($_SERVER['HTTP_X_IMPORT_TOKEN']??'');$expected=(string)($config['import_token']??'');if($expected!==''&&$given!==''&&hash_equals($expected,$given))return;require_admin();if($_SERVER['REQUEST_METHOD']==='POST')csrf_check();}
function findCsvs(string $root): array{$products=[];$categories=[];$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if(!$f->isFile()||mb_strtolower($f->getExtension())!=='csv')continue;$n=mb_strtolower($f->getFilename());$row=['path'=>$f->getPathname(),'size'=>$f->getSize(),'mtime'=>$f->getMTime()];if(str_contains($n,'tovary'))$products[]=$row;elseif(str_contains($n,'categor')||str_contains($n,'category'))$categories[]=$row;}$pick=function(array $a):?string{if(!$a)return null;usort($a,fn($x,$y)=>($y['size']<=>$x['size'])?:($y['mtime']<=>$x['mtime']));return $a[0]['size']>0?$a[0]['path']:null;};return[$pick($products),$pick($categories)];}
function imageIndex(string $root): array{$idx=[];$count=0;$it=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS));foreach($it as $f){if(!$f->isFile())continue;$ext=mb_strtolower($f->getExtension());if(!in_array($ext,['jpg','jpeg','png','webp','gif','avif'],true))continue;$count++;$base=mb_strtolower($f->getFilename());$rel=str_replace(DIRECTORY_SEPARATOR,'/',substr($f->getPathname(),strlen($root)+1));$idx[$base]=$rel;}return[$idx,$count];}
try{authImport($config);if($_SERVER['REQUEST_METHOD']!=='POST')throw new RuntimeException('post_required');$root=realpath(__DIR__.'/../import');if(!$root)throw new RuntimeException('import_missing');[$productFile,$categoryFile]=findCsvs($root);if(!$productFile)throw new RuntimeException('products_csv_missing_or_empty');[$h,$rows,$delimiter,$hasHeader]=csvAll($productFile);if(!$hasHeader){$categoryProbe=null;if($categoryFile){[$ch,$cr,$cd,$chh]=csvAll($categoryFile);$categoryProbe=['rows'=>count($cr),'columns'=>count($ch),'delimiter'=>$cd,'has_header'=>$chh,'first_rows'=>array_slice($cr,0,5)];}[$imgs,$imgCount]=imageIndex($root);$photoMatches=[];foreach(range(0,min(40,count($h)-1)) as $ci){$m=0;$examples=[];foreach(array_slice($rows,0,500) as $r){$cell=trim((string)($r[$ci]??''));if($cell==='')continue;foreach(preg_split('/[|,\r\n]+/u',$cell)?:[] as $ref){$ref=mb_strtolower(basename(str_replace('\\','/',trim($ref," \t\"'"))));if($ref!==''&&isset($imgs[$ref])){$m++;if(count($examples)<3)$examples[]=$ref;break;}}}if($m)$photoMatches[(string)$ci]=['matches_first_500'=>$m,'examples'=>$examples];}out(['ok'=>false,'error'=>'schema_probe_required','source'=>basename($productFile),'total_rows'=>count($rows),'delimiter'=>$delimiter,'columns'=>count($h),'first_rows'=>array_slice($rows,0,5),'category_file'=>$categoryFile?basename($categoryFile):null,'category_probe'=>$categoryProbe,'image_files'=>$imgCount,'photo_column_matches'=>$photoMatches],422);}
$id=col($h,['id','guid','uuid','код','код товара','ид','идентификатор','id товара','id элемента']);$sku=col($h,['sku','артикул','арт','vendorcode','article']);$barcode=col($h,['barcode','штрихкод','штрих код','ean']);$title=col($h,['name','title','наименование','название','товар','название товара']);$price=col($h,['price','цена','розничная цена','цена продажи','price_rub']);$cat=col($h,['category','категория','группа','cat_id','category_id','id категории','раздел']);if($title===null)out(['ok'=>false,'error'=>'title_column_missing','headers'=>$h,'first_rows'=>array_slice($rows,0,3)],422);$total=count($rows);$offset=max(0,(int)($_GET['offset']??0));$limit=min(1000,max(100,(int)($_GET['limit']??500)));$slice=array_slice($rows,$offset,$limit);$categories=[];$catPath=fn(string $key):string=>$key;$byHash=$pdo->prepare('SELECT id,images,specs,description,category_path FROM products WHERE source_hash=? LIMIT 1');$byTitle=$pdo->prepare('SELECT id,images,specs,description,category_path FROM products WHERE title=? ORDER BY is_active DESC,id DESC LIMIT 1');$ins=$pdo->prepare('INSERT INTO products(source_hash,title,price_rub,availability,category_path,specs,description,images,is_active) VALUES(?,?,?,?,?,?,?,?,1)');$upd=$pdo->prepare('UPDATE products SET source_hash=?,title=?,price_rub=?,availability=?,category_path=?,specs=?,description=?,images=?,is_active=1,updated_at=CURRENT_TIMESTAMP WHERE id=?');$created=0;$updated=0;$pdo->beginTransaction();foreach($slice as $r){$t=val($r,$title);if($t==='')continue;$ident=val($r,$id)?:val($r,$sku)?:val($r,$barcode);$hash=hash('sha256','1c|'.($ident!==''?$ident:json_encode($r,JSON_UNESCAPED_UNICODE)));$p=money(val($r,$price));$category=$catPath(val($r,$cat));$byHash->execute([$hash]);$existing=$byHash->fetch();if(!$existing){$byTitle->execute([$t]);$existing=$byTitle->fetch();}$images=$existing['images']??'[]';$specs=$existing['specs']??null;$desc=$existing['description']??null;if($existing){$upd->execute([$hash,$t,$p,'available',$category?:($existing['category_path']??''),$specs,$desc,$images,(int)$existing['id']]);$updated++;}else{$ins->execute([$hash,$t,$p,'available',$category,$specs,$desc,$images]);$created++;}}$pdo->commit();$next=$offset+count($slice);out(['ok'=>true,'offset'=>$offset,'processed'=>count($slice),'total_rows'=>$total,'created'=>$created,'updated'=>$updated,'next_offset'=>$next,'done'=>$next>=$total]);}catch(Throwable $e){if(isset($pdo)&&$pdo->inTransaction())$pdo->rollBack();error_log($e->__toString());out(['ok'=>false,'error'=>$e->getMessage()],500);}
